Через existential теперь выбирается witness требования, а не extension-only helper.

class NoticeFrame {
    private func mark() -> String { "База" }
    func frame() -> String { mark() }
}
class TripFrame: NoticeFrame {
    func mark() -> String { "Поездка" }
}
let frame = TripFrame()
print(frame.mark())
print(frame.frame())

Вывод «Поездка», «База»: private helper базы не переопределён.

protocol Notice {
    func title() -> String
    func detail() -> String
}
extension Notice { func detail() -> String { "Общее" } }
struct TripNotice: Notice {
    func title() -> String { "Поездка" }
    func detail() -> String { "Платформа 3" }
}
struct DelayNotice: Notice {
    func title() -> String { "Задержка" }
    func detail() -> String { "10 минут" }
}
let notice: any Notice = DelayNotice()
print(notice.title())
print(notice.detail())

Вывод «Задержка», «10 минут»; требование маршрутизирует конкретную реализацию.
